const FLAGS_WITH_VALUES = new Set([
    "--cwd",
    "--mode",
    "--model",
    "--prompt",
    "--service-tier",
    "--session-dir",
    "--tier1-threshold",
    "--tier2-threshold",
    "--thinking",
    "--overlap",
    "--window-size",
